script:
test('smallest 2-decimal purchases sit in the 0% band', function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 0.01 }), {
    rebate: 0.00,
    bands: [
      { rate: 0, portion: 0.01, amount: 0.00 },
      { rate: 0.02, portion: 0.00, amount: 0.00 },
      { rate: 0.03, portion: 0.00, amount: 0.00 }
    ]
  });
});

test('purchases of one currency unit sit in the 0% band', function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 1.00 }), {
    rebate: 0.00,
    bands: [
      { rate: 0, portion: 1.00, amount: 0.00 },
      { rate: 0.02, portion: 0.00, amount: 0.00 },
      { rate: 0.03, portion: 0.00, amount: 0.00 }
    ]
  });
});

test('one step below 10000.00 stays in the 0% band', function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 9999.99 }), {
    rebate: 0.00,
    bands: [
      { rate: 0, portion: 9999.99, amount: 0.00 },
      { rate: 0.02, portion: 0.00, amount: 0.00 },
      { rate: 0.03, portion: 0.00, amount: 0.00 }
    ]
  });
});

test('exactly 10000.00 belongs to the lower band and earns nothing', function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 10000.00 }), {
    rebate: 0.00,
    bands: [
      { rate: 0, portion: 10000.00, amount: 0.00 },
      { rate: 0.02, portion: 0.00, amount: 0.00 },
      { rate: 0.03, portion: 0.00, amount: 0.00 }
    ]
  });
});

test('one step above 10000.00 puts only 0.01 in the 2% band', function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 10000.01 }), {
    rebate: 0.00,
    bands: [
      { rate: 0, portion: 10000.00, amount: 0.00 },
      { rate: 0.02, portion: 0.01, amount: 0.0002 },
      { rate: 0.03, portion: 0.00, amount: 0.00 }
    ]
  });
});

test('closest unrounded result below the half cent 0.005', function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 10000.24 }), {
    rebate: 0.00,
    bands: [
      { rate: 0, portion: 10000.00, amount: 0.00 },
      { rate: 0.02, portion: 0.24, amount: 0.0048 },
      { rate: 0.03, portion: 0.00, amount: 0.00 }
    ]
  });
});

test('closest unrounded result above the half cent 0.005', function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 10000.26 }), {
    rebate: 0.01,
    bands: [
      { rate: 0, portion: 10000.00, amount: 0.00 },
      { rate: 0.02, portion: 0.26, amount: 0.0052 },
      { rate: 0.03, portion: 0.00, amount: 0.00 }
    ]
  });
});

test('2% of 0.50 is an exact cent', function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 10000.50 }), {
    rebate: 0.01,
    bands: [
      { rate: 0, portion: 10000.00, amount: 0.00 },
      { rate: 0.02, portion: 0.50, amount: 0.01 },
      { rate: 0.03, portion: 0.00, amount: 0.00 }
    ]
  });
});

test('interior of the 2% band rounds the unequal excess once at the end', function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 23456.78 }), {
    rebate: 269.14,
    bands: [
      { rate: 0, portion: 10000.00, amount: 0.00 },
      { rate: 0.02, portion: 13456.78, amount: 269.1356 },
      { rate: 0.03, portion: 0.00, amount: 0.00 }
    ]
  });
});

test('one step below 50000.00 stays out of the 3% band', function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 49999.99 }), {
    rebate: 800.00,
    bands: [
      { rate: 0, portion: 10000.00, amount: 0.00 },
      { rate: 0.02, portion: 39999.99, amount: 799.9998 },
      { rate: 0.03, portion: 0.00, amount: 0.00 }
    ]
  });
});

test('exactly 50000.00 belongs to the lower band', function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 50000.00 }), {
    rebate: 800.00,
    bands: [
      { rate: 0, portion: 10000.00, amount: 0.00 },
      { rate: 0.02, portion: 40000.00, amount: 800.00 },
      { rate: 0.03, portion: 0.00, amount: 0.00 }
    ]
  });
});

test('one step above 50000.00 puts only 0.01 in the 3% band', function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 50000.01 }), {
    rebate: 800.00,
    bands: [
      { rate: 0, portion: 10000.00, amount: 0.00 },
      { rate: 0.02, portion: 40000.00, amount: 800.00 },
      { rate: 0.03, portion: 0.01, amount: 0.0003 }
    ]
  });
});

test('closest 3% result below an exact half cent', function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 50000.49 }), {
    rebate: 800.01,
    bands: [
      { rate: 0, portion: 10000.00, amount: 0.00 },
      { rate: 0.02, portion: 40000.00, amount: 800.00 },
      { rate: 0.03, portion: 0.49, amount: 0.0147 }
    ]
  });
});

test('closest 3% result above an exact half cent', function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 50000.51 }), {
    rebate: 800.02,
    bands: [
      { rate: 0, portion: 10000.00, amount: 0.00 },
      { rate: 0.02, portion: 40000.00, amount: 800.00 },
      { rate: 0.03, portion: 0.51, amount: 0.0153 }
    ]
  });
});

test('purchases of 60000.00 earn the stated bracket rebate', function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 60000.00 }), {
    rebate: 1100.00,
    bands: [
      { rate: 0, portion: 10000.00, amount: 0.00 },
      { rate: 0.02, portion: 40000.00, amount: 800.00 },
      { rate: 0.03, portion: 10000.00, amount: 300.00 }
    ]
  });
});

test('interior of the 3% band rounds unequal portions once at the end', function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 61234.17 }), {
    rebate: 1137.03,
    bands: [
      { rate: 0, portion: 10000.00, amount: 0.00 },
      { rate: 0.02, portion: 40000.00, amount: 800.00 },
      { rate: 0.03, portion: 11234.17, amount: 337.0251 }
    ]
  });
});
